SELECT cd_gender, cd_marital_status, ship_day_type, total_sales, avg_profit, order_cnt, profit_rank FROM ( SELECT cd_gender, cd_marital_status, ship_day_type, total_sales, avg_profit, order_cnt, DENSE_RANK() OVER (ORDER BY avg_profit DESC) AS profit_rank FROM ( SELECT cd.cd_gender AS cd_gender, cd.cd_marital_status AS cd_marital_status, CASE WHEN d_ship.d_holiday = 'Y' THEN 'Holiday' ELSE 'Non-Holiday' END AS ship_day_type, SUM(ws.ws_ext_sales_price) AS total_sales, AVG(ws.ws_net_profit) AS avg_profit, COUNT(DISTINCT ws.ws_order_number) AS order_cnt FROM web_sales ws JOIN date_dim d_ship ON ws.ws_ship_date_sk = d_ship.d_date_sk JOIN customer_demographics cd ON ws.ws_ship_cdemo_sk = cd.cd_demo_sk JOIN web_site ws_site ON ws.ws_web_site_sk = ws_site.web_site_sk JOIN date_dim d_open ON ws_site.web_open_date_sk = d_open.d_date_sk WHERE d_ship.d_quarter_seq = d_open.d_quarter_seq GROUP BY cd.cd_gender, cd.cd_marital_status, d_ship.d_holiday ) agg ) ranked WHERE profit_rank <= 3 ORDER BY profit_rank, cd_gender
